def calculate_multiple_hashes(data: Union[str, bytes], algorithms: list) -> dict:
    """여러 알고리즘으로 해시를 계산합니다."""
    results = {}

    for algorithm in algorithms:
        if algorithm in hashlib.algorithms_guaranteed:
            results[algorithm] = calculate_data_hash(data, algorithm)
